 if((m=/^Flip a coin\. If heads, this attack does (\d+) more damage\.$/.exec(t)))return coin(1,+m[1],'add');
 if((m=/^This attack does (\d+) more damage for each damage counter on (this Pokémon|your opponent's Active Pokémon)\.$/.exec(t)))return countDamage(m[2]==='this Pokémon'?'self':'opponent',+m[1]/10);
 if(t==='During your opponent\'s next turn, the Defending Pokémon can\'t retreat.')return lock('opponentActive','retreat','opponentTurn');
