 if(t==='Flip a coin. If heads, during your opponent\'s next turn, prevent all damage done to this Pokémon by attacks.')return flip(protect(false));
 if(t==='Flip a coin. If heads, during your opponent\'s next turn, prevent all damage from and effects of attacks done to this Pokémon.')return flip(protect(true));
 if((m=/^During your opponent's next turn, this Pokémon takes (\d+) less damage from attacks \(after applying Weakness and Resistance\)\.$/.exec(t)))return guard(+m[1]);
