 if((m=/^If your opponent's Active Pokémon already has any damage counters on it, this attack does (\d+) more damage\.$/.exec(t)))return bonus(+m[1],'opponentDamaged');
 if((m=/^Search your deck for up to (\d+) Pokémon, reveal them, and put them into your hand\. Then, shuffle your deck\.$/.exec(t)))return search(+m[1]);
 if(t==='Search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck.')return {type:'searchChosen',source:'deck',amount:1,filter:{kind:'trainer',trainerType:'Supporter'}};
 if((m=/^Search your deck for up to (\d+) Basic Pokémon and put them onto your Bench\. Then, shuffle your deck\.$/.exec(t)))return {type:'benchFromDeck',amount:+m[1],filter:{kind:'pokemon',stage:'Basic'},choose:true,optional:true};
 if(t==='Search your deck for a Basic Pokémon and put it onto your Bench. Then, shuffle your deck.')return {type:'benchFromDeck',amount:1,filter:{kind:'pokemon',stage:'Basic'},choose:true};
 if((m=/^This attack also does (\d+) damage to 1 of your opponent's Benched Pokémon\. \(Don't apply Weakness and Resistance for Benched Pokémon\.\)$/.exec(t)))return {type:'benchDamage',side:'opponent',amount:+m[1]};
 if((m=/^This attack does (\d+) damage to 1 of your opponent's Pokémon\. \(Don't apply Weakness and Resistance for Benched Pokémon\.\)$/.exec(t)))return {type:'selectedDamage',target:'opponentPokemon',amount:+m[1]};
