 if(t==='This attack\'s damage isn\'t affected by Resistance.')return {type:'damageRule',ignoreResistance:true};
 if(t==='Flip a coin. If tails, this attack does nothing.')return {type:'coinAttackGate',heads:noop};
 if(t==='Put an Energy attached to this Pokémon into your hand.')return {type:'sm7Rule',rule:'swsh1ReturnAttachments',target:'self',left:1};
 if((m=/^If your opponent's Active Pokémon is a (\w+) Pokémon, this attack does (\d+) more damage\.$/.exec(t)))return {type:'bonusDamage',amount:+m[2],condition:{type:'opponentMatches',filter:{subtype:m[1]}}};
 if((m=/^Heal (\d+) damage from 1 of your Benched Pokémon\.$/.exec(t)))return {type:'heal',amount:+m[1],target:'selfBench'};
 if(t==='You may switch this Pokémon with 1 of your Benched Pokémon.')return {type:'chooseOption',options:[{label:'Switch with a Benched Pokémon',effect:switchSelf},{label:'Stay Active',effect:noop}]};
 if((m=/^If you have more Prize cards remaining than your opponent, this attack does (\d+) more damage\.$/.exec(t)))return bonus(+m[1],'ownPrizesMore');
 if(t==="Flip a coin. If heads, discard a random card from your opponent's hand.")return flip({type:'discardHand',side:'opponent',amount:1,random:true});
 if((m=/^This attack does (\d+) damage for each card in (your hand|your opponent's hand)\.$/.exec(t)))return {type:'handCountDamage',source:m[2]==='your hand'?'self':'opponent',amount:+m[1],mode:'replace'};
 if((m=/^Put (\d+) damage counters on 1 of your opponent's Pokémon\.$/.exec(t)))return {type:'sm7Rule',rule:'sm12FixedCounters',left:1,amount:10*+m[1]};
