 if((m=/^This attack does (\d+) more damage for each of your opponent's Benched Pokémon\.$/.exec(t)))return {type:'benchCountDamage',side:'opponent',amount:+m[1],mode:'add'};
 if(t==="Heal from this Pokémon the same amount of damage you did to your opponent's Active Pokémon.")return {type:'drain'};
 if((m=/^If your opponent's Active Pokémon is an Evolution Pokémon, this attack does (\d+) more damage\.$/.exec(t)))return {type:'bonusDamage',amount:+m[1],condition:{type:'opponentMatches',filter:{evolved:true}}};
 if((m=/^This attack also does (\d+) damage to each of your Benched Pokémon\. \(Don't apply Weakness and Resistance for Benched Pokémon\.\)$/.exec(t)))return {type:'benchDamage',side:'self',all:true,amount:+m[1]};
 if((m=/^During your next turn, this Pokémon can't use (.+)\.$/.exec(t)))return {...lock('self','attack','nextOwnTurn'),attackName:m[1]};
 if((m=/^If there are (\d+) or fewer cards in your deck, this attack does (\d+) more damage\.$/.exec(t)))return {type:'bonusDamage',amount:+m[2],condition:{type:'sm12DeckAtMost',amount:+m[1]}};
 if((m=/^Heal (\d+) damage from 1 of your Pokémon\.$/.exec(t)))return {type:'chooseTarget',target:'selfPokemon',effect:{type:'heal',amount:+m[1],target:'selfPokemon'}};
 if((m=/^If you played a Supporter card from your hand during this turn, this attack does (\d+) more damage\.$/.exec(t)))return bonus(+m[1],'supporterPlayed');
 if((m=/^This attack does (\d+) damage for each Energy card in your opponent's discard pile\.$/.exec(t)))return {type:'sm7Rule',rule:'sm9DiscardEnergyDamage',amount:+m[1]};
 if((m=/^Attach a Basic (\w+) Energy card from your hand to 1 of your Benched Pokémon\.$/.exec(t)))return {type:'sm7Rule',rule:'sm12HandAttach',left:1,energyType:m[1],basicOnly:true,benchOnly:true};
 if((m=/^Search your deck for a Basic (\w+) Energy card and attach it to this Pokémon\. Then, shuffle your deck\.$/.exec(t)))return {type:'sm7Rule',rule:'sm9SearchAttach',amount:1,energyTypes:[m[1]],sourceSelf:true};
 if((m=/^Attach up to 2 Basic (\w+) Energy cards from your discard pile to 1 of your Pokémon\.$/.exec(t)))return {type:'sm7Rule',rule:'sm12DiscardAttach',left:2,energyType:m[1],basicOnly:true,sameTarget:true,optional:true};
 if((m=/^If any of your Pokémon were Knocked Out by damage from an attack during your opponent's last turn, this attack does (\d+) more damage\.$/.exec(t)))return bonus(+m[1],'koByOpponentAttackLastTurn');
 if(t==='Search your deck for an Energy card, reveal it, and put it into your hand. Then, shuffle your deck.')return {type:'searchChosen',source:'deck',amount:1,filter:{kind:'energy'}};
 if(t==="Before doing damage, discard all Pokémon Tools from your opponent's Active Pokémon.")return {type:'discardTool',target:'opponentActive',amount:'all',timing:'beforeDamage'};
 if((m=/^This attack also does (\d+) damage to 1 of your Benched Pokémon\. \(Don't apply Weakness and Resistance for Benched Pokémon\.\)$/.exec(t)))return {type:'benchDamage',side:'self',amount:+m[1]};
 if(t==="Shuffle your hand into your deck. Then, draw a card for each Benched Pokémon (both yours and your opponent's).")return {type:'handShuffle',draw:'bothBenchCount'};
 if(t==="Flip a coin. If heads, your opponent's Active Pokémon is now Poisoned. During Pokémon Checkup, put 2 damage counters on that Pokémon instead of 1.")return flip({...status('poison'),amount:20});
 if((m=/^If you attached a Pokémon Tool card from your hand to this Pokémon during this turn, this attack does (\d+) more damage\.$/.exec(t)))return bonus(+m[1],'sm10ToolNow');
 if((m=/^If this Pokémon is affected by a Special Condition, this attack does (\d+) more damage\.$/.exec(t)))return bonus(+m[1],'selfStatus');
 if(t==='This Pokémon is now Burned.')return {type:'status',target:'self',status:'burn'};
 if((m=/^If this Pokémon has (\d+) or more damage counters on it, this attack does nothing\.$/.exec(t)))return {type:'attackRequirement',condition:{type:'selfDamageBelow',amount:10*+m[1]},allowWhenFailed:true};
 if(t==="Move all damage counters from 1 of your Benched Pokémon to your opponent's Active Pokémon.")return {type:'chooseTarget',target:'selfBench',effect:{type:'moveDamage',target:'selfBench',destination:'opponentActive',amount:'all'}};
 if((m=/^Discard any number of Pokémon Tool cards from your hand\. This attack does (\d+) damage for each card you discarded in this way\.$/.exec(t)))return {type:'chooseDiscardForBonus',zone:'hand',max:30,amount:+m[1],filter:{kind:'trainer',trainerType:'Tool'}};
 if((m=/^Attach a Basic (\w+) Energy card from your discard pile to 1 of your Benched Pokémon\.$/.exec(t)))return {type:'sm7Rule',rule:'sm12DiscardAttach',left:1,energyType:m[1],basicOnly:true,benchOnly:true};
 if((m=/^If this Pokémon was healed during this turn, this attack does (\d+) more damage\.$/.exec(t)))return bonus(+m[1],'xy8HealedThisTurn');
